#define main legacy_main
#include "../upsample-cuda/main.cu"
#undef main
#include <vector>
#include <fstream>
#include <iostream>
#include <iomanip>
struct Case{int B,C,H,W,S;std::vector<float>x,g,y,dx;float*a,*dg,*o,*dd;};
int main(){std::vector<Case>cases;std::vector<float>prefix;for(auto shape:std::vector<std::vector<int>>{{2,3,7,11},{1,2,32,33}}){Case c;c.B=shape[0];c.C=shape[1];c.H=shape[2];c.W=shape[3];c.S=c.B*c.C*c.H*c.W;c.x.resize(c.S);c.g.resize(4*c.S);c.y.resize(4*c.S);c.dx.resize(c.S);for(int i=0;i<c.S;i++)c.x[i]=float((i*13)%67-33)/16;for(int i=0;i<4*c.S;i++)c.g[i]=float((i*17)%71-35)/16;upsample_forward_reference(c.x.data(),c.y.data(),c.B,c.C,c.H,c.W);upsample_backward_reference(c.g.data(),c.dx.data(),c.B,c.C,c.H,c.W);cudaMalloc(&c.a,c.S*4);cudaMalloc(&c.dg,c.S*16);cudaMalloc(&c.o,c.S*16);cudaMalloc(&c.dd,c.S*4);cudaMemcpy(c.a,c.x.data(),c.S*4,cudaMemcpyHostToDevice);cudaMemcpy(c.dg,c.g.data(),c.S*16,cudaMemcpyHostToDevice);prefix.insert(prefix.end(),c.x.begin(),c.x.end());prefix.insert(prefix.end(),c.g.begin(),c.g.end());for(int x:{c.B,c.C,c.H,c.W,3})prefix.push_back(x);cases.push_back(c);}std::vector<std::pair<int,int>>variants;for(int k=1;k<=4;k++){if(k==1||k==3){for(int b:{32,64,128,256,512,1024})variants.push_back({k,b});}else for(int b:{8,16,32})variants.push_back({k,b});}
auto run=[&](Case&c,int k,int bs,std::vector<float>&out){float*target=k<=2?c.o:c.dd;auto&ref=k<=2?c.y:c.dx;cudaMemset(target,255,ref.size()*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int r=0;r<3;r++){if(k==1)upsample_forward1(c.o,c.a,c.B,c.C,c.H,c.W,bs);else if(k==2)upsample_forward2(c.o,c.a,c.B,c.C,c.H,c.W,bs,bs);else if(k==3)upsample_backward1(c.dd,c.dg,c.B,c.C,c.H,c.W,bs);else upsample_backward2(c.dd,c.dg,c.B,c.C,c.H,c.W,bs,bs);}cudaDeviceSynchronize();double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;std::vector<float>got(ref.size());cudaMemcpy(got.data(),target,got.size()*4,cudaMemcpyDeviceToHost);bool ok=got==ref&&cudaGetLastError()==cudaSuccess;out.insert(out.end(),got.begin(),got.end());return std::make_pair(t,ok);};std::vector<float>tmp;for(auto&c:cases)for(auto[k,b]:variants)run(c,k,b,tmp);for(int trial=1;trial<=5;trial++){auto out=prefix;double elapsed=0;bool ok=true;std::cout<<"STUDY_COMPONENT_SECONDS ";for(auto&c:cases)for(auto[k,b]:variants){auto[t,pass]=run(c,k,b,out);elapsed+=t;ok&=pass;std::cout<<std::setprecision(17)<<t<<",";}std::cout<<std::endl;std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();std::cout<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":0,\"timing_region\":\"sum36_three_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"float32\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}"<<std::endl;if(!ok)return 2;}}
